    /// <summary>Every code that has a hint, in ordinal order.</summary>
    public static IReadOnlyList<string> Codes => [.. Table.Keys.Order(StringComparer.Ordinal)];

    /// <summary>The hint for a code, or null when there is none.</summary>
    /// <param name="code">The code.</param>
    public static string? For(string code)
    {
        ArgumentNullException.ThrowIfNull(code);
        return Table.GetValueOrDefault(code);
    }
